#!/usr/bin/env bash
# Tests for the additive merge of the shared root files (lib/additive.sh, #716, part 1 of #676). Offline.
#   additive_merge <name> <base> <ours> <theirs>   prints the merge of a package.json or a Markdown file; 1 and the reason
#                                                  on stderr when the change is not purely additive
#   additive_resolve <root> <path> <b> <o> <t>     resolves a conflicted file of <root> and stages it; a lockfile is
#                                                  regenerated by the install command of its package manager
set -u
here=$(cd "$(dirname "$0")" && pwd)
SELF=$here/../senior-mode
LIB=$here/../lib
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
failures=0

fail() { echo "FAIL: $*"; failures=$((failures + 1)); }

# shellcheck disable=SC1090,SC1091 # the modules are definitions only
for m in common config additive; do . "$LIB/$m.sh"; done

# package.json: each side adds a different script.
printf '%s\n' '{"name":"x","scripts":{"test":"t"},"dependencies":{"a":"1"}}' >"$work/base.json"
printf '%s\n' '{"name":"x","scripts":{"test":"t","lint":"l"},"dependencies":{"a":"1"}}' >"$work/ours.json"
printf '%s\n' '{"name":"x","scripts":{"test":"t","build":"b"},"dependencies":{"a":"1","b":"2"}}' >"$work/theirs.json"
additive_merge package.json "$work/base.json" "$work/ours.json" "$work/theirs.json" >"$work/out" 2>"$work/err" ||
  fail "the union was refused: $(cat "$work/err")"
jq -e '.scripts == {test: "t", lint: "l", build: "b"} and .dependencies == {a: "1", b: "2"} and .name == "x"' "$work/out" >/dev/null ||
  fail "the merge does not hold both scripts: $(cat "$work/out")"
[ "$(jq -r '.scripts | keys_unsorted | join(",")' "$work/out")" = test,lint,build ] || fail "ours does not come first"

# The same script set to two commands fails and names the key.
printf '%s\n' '{"name":"x","scripts":{"test":"t","lint":"eslint"},"dependencies":{"a":"1"}}' >"$work/theirs2.json"
additive_merge package.json "$work/base.json" "$work/ours.json" "$work/theirs2.json" >"$work/out" 2>"$work/err" &&
  fail "two commands for one script were merged"
grep -q 'scripts.lint' "$work/err" || fail "the key is not named: $(cat "$work/err")"
# A key that one side removed is not an addition.
printf '%s\n' '{"name":"x","scripts":{},"dependencies":{"a":"1"}}' >"$work/theirs3.json"
additive_merge package.json "$work/base.json" "$work/ours.json" "$work/theirs3.json" >/dev/null 2>"$work/err" &&
  fail "a removed script was merged"
grep -q 'scripts.test' "$work/err" || fail "the removed key is not named: $(cat "$work/err")"

# Markdown: both sections appended after unchanged text, ours first; an edited line fails.
printf '# R\n\nintro\n' >"$work/base.md"
printf '# R\n\nintro\n\n## Ours\n' >"$work/ours.md"
printf '# R\n\nintro\n\n## Theirs\n' >"$work/theirs.md"
additive_merge README.md "$work/base.md" "$work/ours.md" "$work/theirs.md" >"$work/out" 2>"$work/err" ||
  fail "the append was refused: $(cat "$work/err")"
[ "$(cat "$work/out")" = "$(printf '# R\n\nintro\n\n## Ours\n\n## Theirs')" ] || fail "both sections, ours first: $(cat "$work/out")"
printf '# R\n\nintro edited\n\n## Theirs\n' >"$work/edit.md"
additive_merge README.md "$work/base.md" "$work/ours.md" "$work/edit.md" >/dev/null 2>"$work/err" && fail "an edited line was merged"
grep -q 'not an addition' "$work/err" || fail "no reason for the edited line: $(cat "$work/err")"

# A lockfile is regenerated by the install command of its package manager and staged, never merged.
root=$work/repo
git init -q -b main "$root"
mkdir -p "$work/bin"
cat >"$work/bin/pnpm" <<'STUB'
#!/usr/bin/env bash
echo "$*" >"$PWD/pnpm-args"
grep -q '^<<<<<<<' pnpm-lock.yaml && exit 1
echo "regenerated" >pnpm-lock.yaml
STUB
chmod +x "$work/bin/pnpm"
printf 'lock: ours\n' >"$work/ours.lock"
printf '<<<<<<< ours\nx\n=======\ny\n>>>>>>> theirs\n' >"$root/pnpm-lock.yaml"
(cd "$root" && PATH=$work/bin:$PATH additive_resolve "$root" pnpm-lock.yaml "$work/ours.lock" "$work/ours.lock" "$work/ours.lock") 2>"$work/err" ||
  fail "the lockfile was not resolved: $(cat "$work/err")"
[ "$(cat "$root/pnpm-args" 2>/dev/null)" = "install --lockfile-only" ] || fail "install command: $(cat "$root/pnpm-args" 2>/dev/null)"
[ "$(cat "$root/pnpm-lock.yaml")" = regenerated ] || fail "the lockfile was not regenerated"
git -C "$root" diff --cached --name-only | grep -qx pnpm-lock.yaml || fail "the lockfile is not staged"
additive_merge pnpm-lock.yaml "$work/ours.lock" "$work/ours.lock" "$work/ours.lock" >/dev/null 2>&1 && fail "a lockfile was merged as text"

# serve.sharedPaths: an array of root files passes `config validate`, anything else fails and names the key.
repo=$work/cfg
git init -q -b main "$repo"
mkdir -p "$repo/.claude"
run() { (cd "$repo" && "$SELF" "$@") >"$work/out" 2>"$work/err"; }
echo '{"serve":{"sharedPaths":["package.json","README.md"]}}' >"$repo/.claude/senior-mode.json"
run config validate || fail "sharedPaths: a list was refused: $(cat "$work/out")"
echo '{"serve":{"sharedPaths":"package.json"}}' >"$repo/.claude/senior-mode.json"
run config validate && fail "sharedPaths: a string passed"
grep -q '^error: serve.sharedPaths: expected array' "$work/out" || fail "sharedPaths: the key is not named: $(cat "$work/out")"

exit "$failures"
